insert into public.editions (year, slug, name, theme, theme_statement, event_date, start_time, end_time, timezone, venue_name, venue_institution, venue_address, venue_notes, expected_attendance, status, registration_url, registration_note, event_day_mode, post_event_mode, is_current, highlights, host_institution, poster_deadline, poster_requirements, abstract_config)
insert into public.rooms (edition_id, name, building, floor, directions, capacity, sort) select id, 'Main lecture theatre (to be confirmed)', 'Lincoln Medical School', null, 'Signage and volunteers will direct you on arrival.', null, 0 from _ed;
insert into public.workshops (edition_id, slug, number, title, strapline, summary, description, topics, outcomes, audience, facilitator, facilitator_bio, capacity, booking_enabled, accent, motif, notes) select id, 'from-writing-to-publishing', 1, 'From Writing to Publishing', 'Turn research into a publication.', 'Explore the process of transforming research into academic publications.', 'This workshop follows a piece of research from first draft to published paper. It looks at how manuscripts are structured, how to choose a journal that fits your work, what happens during peer review and how to respond to reviewers, and how to plan a realistic publication strategy as a student.', array['Manuscript structure', 'Journal selection', 'Peer review', 'Publication strategy']::text[], array['Describe the standard structure of a research manuscript', 'Weigh up factors when choosing a target journal', 'Understand how peer review works and how to respond to reviewer comments', 'Plan next steps for publishing your own work']::text[], 'Students with a project in progress or completed, and anyone considering their first publication.', null, null, null, false, 'electric', 'manuscript', null from _ed;
insert into public.workshops (edition_id, slug, number, title, strapline, summary, description, topics, outcomes, audience, facilitator, facilitator_bio, capacity, booking_enabled, accent, motif, notes) select id, 'digital-health-in-clinical-practice', 2, 'Digital Health in Clinical Practice', 'Cases, data and decisions.', 'Interactive clinical cases exploring the application of digital tools, data and evidence-based decision-making.', 'Working through interactive clinical cases, participants will consider where digital tools and data can support clinical decisions, what evidence should be expected before a tool is adopted, and where the limits and risks lie.', array['Clinical cases', 'Digital tools', 'Data in decision-making', 'Evaluating evidence']::text[], array['Discuss how digital tools can inform clinical decisions', 'Identify the evidence needed before adopting a digital intervention', 'Recognise risks, limitations and unintended consequences']::text[], 'All delegates. No prior technical knowledge is needed.', null, null, null, false, 'cyan', 'pulse', null from _ed;
insert into public.workshops (edition_id, slug, number, title, strapline, summary, description, topics, outcomes, audience, facilitator, facilitator_bio, capacity, booking_enabled, accent, motif, notes) select id, 'evidence-based-medicine-in-practice', 3, 'Evidence-Based Medicine in Practice', 'Read critically. Decide well.', 'Develop critical appraisal skills and understand how evidence informs clinical decisions.', 'A practical introduction to critical appraisal. Participants will work through published research, assess its validity and relevance, and discuss how evidence is weighed alongside clinical judgement and patient preferences.', array['Critical appraisal', 'Study design', 'Bias and validity', 'Applying evidence']::text[], array['Apply a structured approach to appraising a research paper', 'Recognise common sources of bias', 'Explain how evidence informs, but does not replace, clinical judgement']::text[], 'Students at any stage who want to read research with more confidence.', null, null, null, false, 'violet', 'evidence', null from _ed;
insert into public.workshops (edition_id, slug, number, title, strapline, summary, description, topics, outcomes, audience, facilitator, facilitator_bio, capacity, booking_enabled, accent, motif, notes) select id, 'building-a-competitive-clinical-portfolio', 4, 'Building a Competitive Clinical Portfolio', 'Document what you have done. Plan what comes next.', 'Explore practical approaches to documenting achievements, identifying opportunities and developing an academic or clinical portfolio.', 'This workshop looks at how to build a portfolio that reflects your interests and achievements. It covers documenting activity as you go, finding meaningful opportunities in research, teaching and leadership, and presenting your experience clearly.', array['Recording achievements', 'Finding opportunities', 'Academic portfolios', 'Reflection']::text[], array['Set up a simple system for recording achievements', 'Identify opportunities that match your interests', 'Present your experience clearly and honestly']::text[], 'Students in any year, particularly those thinking about foundation and specialty applications.', null, null, null, false, 'electric', 'portfolio', null from _ed;
insert into public.workshops (edition_id, slug, number, title, strapline, summary, description, topics, outcomes, audience, facilitator, facilitator_bio, capacity, booking_enabled, accent, motif, notes) select id, 'digital-surgery-and-simulation', 5, 'Digital Surgery and Simulation', 'Where surgical training meets technology.', 'Explore how digital technologies, simulation and emerging surgical tools may influence surgical education and practice.', 'An exploration of how simulation and digital technologies are being used in surgical education and practice, and what evidence exists for their benefits. Any hands-on demonstrations or equipment will be announced once confirmed by the facilitators.', array['Simulation-based education', 'Emerging surgical technology', 'Skills assessment', 'Evidence for new tools']::text[], array['Describe how simulation is used in surgical training', 'Discuss the potential and limitations of emerging surgical technologies', 'Consider how the impact of new surgical tools can be evaluated']::text[], 'Students with an interest in surgery, simulation or medical technology.', null, null, null, false, 'cyan', 'simulation', 'Interactive demonstrations will be listed here if confirmed.' from _ed;
insert into public.workshops (edition_id, slug, number, title, strapline, summary, description, topics, outcomes, audience, facilitator, facilitator_bio, capacity, booking_enabled, accent, motif, notes) select id, 'global-digital-health-inequalities', 6, 'Global Digital Health Inequalities', 'Who benefits from digital health, and who is left behind?', 'Explore how access, infrastructure, socioeconomic factors and healthcare systems influence the adoption and impact of digital healthcare technologies.', 'Digital health can widen or narrow inequalities. This workshop examines how access, connectivity, digital literacy, socioeconomic factors and the design of healthcare systems shape who benefits from new technology, in the UK and globally.', array['Digital exclusion', 'Infrastructure and access', 'Health systems', 'Equitable design']::text[], array['Identify factors that influence access to digital healthcare', 'Discuss how digital interventions can widen or reduce inequalities', 'Consider principles for more equitable digital health']::text[], 'All delegates, especially those interested in public and global health.', null, null, null, false, 'violet', 'globe', null from _ed;
insert into public.sessions (edition_id, slug, title, category, starts_at, ends_at, room_id, description, objectives, capacity, is_provisional, sort) select id, 'arrival-and-registration', 'Arrival and registration', 'networking', null, null, null, 'Collect your delegate badge, find your way around the venue and meet fellow delegates before the opening session.', '{}'::text[], null, true, 10 from _ed;
insert into public.sessions (edition_id, slug, title, category, starts_at, ends_at, room_id, description, objectives, capacity, is_provisional, sort) select id, 'welcome-and-opening', 'Welcome and opening address', 'keynote', null, null, (select id from public.rooms where name = 'Main lecture theatre (to be confirmed)' limit 1), 'An introduction to INSPIRE 2026 and this year''s theme, Digital Health: From Innovation to Evidence.', array['Understand the shape of the day', 'Hear the framing for this year''s theme']::text[], null, true, 20 from _ed;
insert into public.sessions (edition_id, slug, title, category, starts_at, ends_at, room_id, description, objectives, capacity, is_provisional, sort) select id, 'keynote-presentation-1', 'Keynote presentation', 'keynote', null, null, (select id from public.rooms where name = 'Main lecture theatre (to be confirmed)' limit 1), 'A keynote from a healthcare or research professional exploring digital health and its evidence base. Speaker announcement coming soon.', '{}'::text[], null, true, 30 from _ed;
insert into public.sessions (edition_id, slug, title, category, starts_at, ends_at, room_id, description, objectives, capacity, is_provisional, sort) select id, 'workshop-session-1', 'Interactive workshops: first rotation', 'workshop', null, null, null, 'Clinician-led, small-group workshops. Choose from the six workshop areas; allocations and rooms will be confirmed by the conference team.', array['Practise a skill in a small-group setting', 'Discuss real cases with clinicians']::text[], null, true, 40 from _ed;
insert into public.sessions (edition_id, slug, title, category, starts_at, ends_at, room_id, description, objectives, capacity, is_provisional, sort) select id, 'lunch-and-networking', 'Lunch and networking', 'break', null, null, null, 'Time to eat, recharge and talk with delegates, presenters and clinicians.', '{}'::text[], null, true, 50 from _ed;
insert into public.sessions (edition_id, slug, title, category, starts_at, ends_at, room_id, description, objectives, capacity, is_provisional, sort) select id, 'poster-presentations', 'Student research poster presentations', 'research', null, null, null, 'Accepted presenters share their work with delegates and judges. Browse posters, ask questions and discuss methods and findings.', array['Engage with student research across disciplines', 'Practise discussing research with presenters']::text[], null, true, 60 from _ed;
insert into public.sessions (edition_id, slug, title, category, starts_at, ends_at, room_id, description, objectives, capacity, is_provisional, sort) select id, 'keynote-presentation-2', 'Keynote presentation', 'keynote', null, null, (select id from public.rooms where name = 'Main lecture theatre (to be confirmed)' limit 1), 'A second keynote presentation. Speaker announcement coming soon.', '{}'::text[], null, true, 70 from _ed;
insert into public.sessions (edition_id, slug, title, category, starts_at, ends_at, room_id, description, objectives, capacity, is_provisional, sort) select id, 'workshop-session-2', 'Interactive workshops: second rotation', 'workshop', null, null, null, 'A second opportunity to attend a clinician-led workshop. Allocations and rooms will be confirmed by the conference team.', '{}'::text[], null, true, 80 from _ed;
