insert into public.resources (title, category, summary, url, is_example, published, sort) values ('EQUATOR Network reporting guidelines', 'Writing & reporting', 'The central library of reporting guidelines such as CONSORT, STROBE and PRISMA, useful when structuring an abstract or manuscript.', 'https://www.equator-network.org/', false, true, 0);
insert into public.resources (title, category, summary, url, is_example, published, sort) values ('CASP critical appraisal checklists', 'Critical appraisal', 'Structured checklists for appraising randomised trials, cohort studies, systematic reviews and more.', 'https://casp-uk.net/casp-tools-checklists/', false, true, 1);
